<article class="game-card"><a class="game-cover" href="<?= e(url('game',['id'=>$g['id']])) ?>"><?php if ($g['imagem']): ?><img class="cover-backdrop" src="<?= e(asset('images/'.cardImage($g['imagem']))) ?>" alt="" aria-hidden="true" loading="lazy"><img class="cover-image" src="<?= e(asset('images/'.cardImage($g['imagem']))) ?>" alt="Capa de <?= e($g['titulo']) ?>" loading="lazy"><?php else: ?><span class="placeholder">G<span class="accent">↗</span></span><?php endif; ?><span class="cover-platform"><?= e($g['plataforma']) ?></span></a><div class="game-body"><span class="eyebrow category-label"><?= e($g['categoria']) ?></span><h3><a href="<?= e(url('game',['id'=>$g['id']])) ?>"><?= e($g['titulo']) ?></a></h3><span class="muted edition"><?= e($g['sistemas']) ?></span><div class="game-bottom"><strong class="price"><?= money($g['preco']) ?></strong><a class="round-link" aria-label="Detalhes de <?= e($g['titulo']) ?>" href="<?= e(url('game',['id'=>$g['id']])) ?>">↗</a></div><small class="stock <?= !$g['estoque']?'sold-out':'' ?>"><?= $g['estoque'] ? '● '.$g['estoque'].' unidades disponíveis' : 'Sem estoque' ?></small></div></article>
